`articles_list_published` accepts a required integer `page` (1–100), returns 12 articles per page, and excludes drafts on the host. I’ll count null, empty, or whitespace-only descriptions as empty and follow `nextPage` until null.

```php
$page = 1;
$checked = 0;
$listCalls = 0;
$matches = [];
$seenPages = [];

do {
    if (isset($seenPages[$page])) {
        throw new RuntimeException("Repeated pagination page");
    }
    $seenPages[$page] = true;

    $result = $tools->call("articles_list_published", ["page" => $page]);
    $listCalls++;

    $articles = $result->articles ?? $result->items ?? $result->data ?? null;
    if (!is_array($articles) || !property_exists($result, "nextPage")) {
        return [
            "complete" => false,
            "reason" => "Unexpected response structure",
            "checked" => $checked,
            "matches" => $matches,
            "list_calls" => $listCalls,
            "response" => $result,
        ];
    }

    foreach ($articles as $article) {
        if (!property_exists($article, "id")
            || !property_exists($article, "title")
            || !property_exists($article, "meta_description")) {
            throw new RuntimeException("Missing article fields");
        }

        $checked++;
        $description = $article->meta_description;
        if ($description === null || trim($description) === "") {
            $matches[] = [
                "id" => $article->id,
                "title" => $article->title,
            ];
        }
    }

    $page = $result->nextPage;
} while ($page !== null);

return [
    "complete" => true,
    "checked" => $checked,
    "matches" => $matches,
    "list_calls" => $listCalls,
];
```

